import{_ as t,o,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"Ref(Map)","description":"结论先行： 把 openOrderData 改成 const openOrderData ref(new Map\\\\<number, UnfoldOrderRow\\\\ ()) 后， Map 依旧只是“浅层”代理 ——Vue 会拦截 set / delete / clear 等操作来触。","frontmatter":{"title":"Ref(Map)","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"结论先行： 把 openOrderData 改成 const openOrderData ref(new Map\\\\<number, UnfoldOrderRow\\\\ ()) 后， Map 依旧只是“浅层”代理 ——Vue 会拦截 set / delete / clear 等操作来触。","sidebarWeight":138,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/Vue 3 响应式 Map 全攻略/Ref(Map).md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/Vue 3 响应式 Map 全攻略/Ref(Map).md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/Vue 3 响应式 Map 全攻略/Ref(Map).md"}'),d={name:"posts/Vue系统教程/03-响应式与组合式 API/Vue 3 响应式 Map 全攻略/Ref(Map).md"};function n(s,e,c,l,p,i){return o(),r("div",null,[...e[0]||(e[0]=[a('<div><h1 id="ref-map" tabindex="-1">Ref(Map) <a class="header-anchor" href="#ref-map" aria-label="Permalink to &quot;Ref(Map)&quot;">​</a></h1><blockquote><p>本节目标：理解“Ref(Map)”的核心思路，并能把它用于实际开发或面试表达。 <strong><strong>结论先行：</strong></strong> 把 <code>openOrderData</code> 改成 const openOrderData = ref(new Map&lt;number, UnfoldOrderRow&gt;())</p></blockquote><p>后，<strong><strong>Map 依旧只是“浅层”代理</strong></strong>——Vue 会拦截 <code>set / delete / clear</code> 等操作来触发依赖收集，但你往里 <code>set</code> 的每一条 <code>row</code> 并不会被自动 <code>reactive()</code>。所以子属性仍然不是深度响应式，除非你在写入时手动包一层 <code>reactive(row)</code>。</p><h3 id="为什么" tabindex="-1">为什么？ <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么？&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>写法</strong></td><td><strong>Map 本身是否代理</strong></td><td><strong>value 自动深层代理？</strong></td><td><strong>操作语法</strong></td></tr><tr><td>reactive(new Map())</td><td>✅（返回 Proxy）</td><td>❌</td><td>直接 .set() / .delete()</td></tr><tr><td>ref(new Map())</td><td>✅（但包在 .value 里）</td><td>❌</td><td>openOrderData.value.set()</td></tr></tbody></table><ul><li><strong><strong>ref</strong></strong> 只是给这整个 Map 再加了一层壳，需要通过 <code>.value</code> 访问。但里面的 Map 结构和行为与 <code>reactive(new Map())</code> <strong><strong>完全一样</strong></strong>：只有键级别是可追踪的。</li><li>当你这样写： openOrderData.value.set(ticket, row) // row 是普通对象 模板或 <code>watch</code> 在访问 <code>row.xxx</code> 时并不会追踪到后续的 <code>row.xxx = ...</code>，因为 <code>row</code> 不是 Proxy。</li></ul><h3 id="正确姿势-保持深度响应" tabindex="-1">正确姿势（保持深度响应） <a class="header-anchor" href="#正确姿势-保持深度响应" aria-label="Permalink to &quot;正确姿势（保持深度响应）&quot;">​</a></h3><ul><li>openOrderData.value.set(ticket, row)</li></ul><ul><li>// 保证子对象可追踪</li><li>openOrderData.value.set(ticket, reactive(row) as any)</li></ul><p>用 <code>reactive()</code> 包装一次就够了——后续你 <code>Object.assign(exist, patch)</code>、或直接 <code>exist.PROFIT = x</code> 都会触发视图 / 计算属性更新。</p><h3 id="何时选-reactive-map-vs-ref-map" tabindex="-1">何时选** <strong><code>reactive(Map)</code></strong> <strong>vs</strong> **<code>ref(Map)</code>****？ <a class="header-anchor" href="#何时选-reactive-map-vs-ref-map" aria-label="Permalink to &quot;何时选** **`reactive(Map)`** **vs** **`ref(Map)`****？&quot;">​</a></h3><ul><li><strong><strong>组件模板里经常读取</strong> <strong><code>map</code></strong> <strong>的 size、entries 等</strong></strong> → <code>reactive</code> 更直观（无需 <code>.value</code>）</li><li><strong><strong>需要在多个地方复用 Map 并希望替换整个 Map 对象</strong></strong> → <code>ref</code> 方便你直接 <code>openOrderData.value = new Map()</code> 来触发更新</li><li>无论哪种，**<strong>value 本身都要自己</strong> <strong><code>reactive</code></strong>******，这点是一样的。</li></ul><p>&gt; <strong><strong>要点回顾</strong></strong> &gt; - <code>Map</code> 的键层级可追踪，值需要手动 <code>reactive</code>。 &gt; - <code>ref(new Map())</code> 不会带来自带深层代理。 &gt; - 更新已有 Proxy 上的属性可用 <code>Object.assign</code>；新增属性在首次依赖收集后才能被追踪。</p></div>',1)])])}const f=t(d,[["render",n]]);export{u as __pageData,f as default};
